def valid_date(date):
    if date == "":
        return False

    parts = date.split('-')

    if len(parts) != 3:
        return False

    month_str, day_str, year_str = parts

    try:
        month = int(month_str)
        day = int(day_str)
        year = int(year_str)

        # Check for leading zeros or invalid characters that might cause parsing issues but are not strictly forbidden by format description (though examples imply strict mm-dd-yyyy with digits only)
        if len(month_str) != 2 or len(day_str) != 4: 
            return False

    except ValueError:
        return False

    # Rule 3: Month validation
    if month < 1 or month > 12:
        return False

    # Rule 2 & Format check for day count based on month
    max_days = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31] # Index 1 to 12

    if month in [4, 6, 9, 11]:
        max_days[month] = 30
    elif month == 2:
        # Leap year check for February
        is_leap = (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)
        if day > 29:
            return False
    else:
        max_days[month] = 31

    # Rule 2 continued: Day validation
    if day < 1 or day > max_days[month]:
        return False

    return True

